<article class="card adminPackageCard"><header><div><span class="eyebrow"><?=h(strtoupper((string)$p['slug']))?></span><h2><?=h((string)$p['name'])?></h2></div><span class="badge"><?=h((string)$accountCount)?> account<?= $accountCount===1?'':'s' ?></span></header>
<form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="update_package"><input type="hidden" name="package_id" value="<?=h((string)$p['public_id'])?>">
